"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import { DiagramFrame } from "@diax/ui-react/presentation";
import type { DiaxRelation } from "diax";
import type { ReactNode } from "react";

const participants = [
  { id: "owner", label: "Owner", detail: "Sets intent" },
  { id: "agent", label: "Agent", detail: "Builds change" },
  { id: "verifier", label: "Verifier", detail: "Checks evidence" },
  { id: "store", label: "Artifact store", detail: "Preserves receipt" },
] as const;

type ParticipantId = (typeof participants)[number]["id"];
type MessageKind = "request" | "return" | "write";

interface Message {
  id: string;
  from: ParticipantId;
  to: ParticipantId;
  label: string;
  detail: string;
  kind: MessageKind;
}

const messages = [
  {
    id: "m01-brief",
    from: "owner",
    to: "agent",
    label: "Implementation brief",
    detail: "Scope, constraints and accepted seam",
    kind: "request",
  },
  {
    id: "m02-evaluate",
    from: "agent",
    to: "verifier",
    label: "Candidate + tests",
    detail: "Source, fixtures and expected behavior",
    kind: "request",
  },
  {
    id: "m03-findings",
    from: "verifier",
    to: "agent",
    label: "Review findings",
    detail: "Exact failures and repair targets",
    kind: "return",
  },
  {
    id: "m04-receipt",
    from: "agent",
    to: "store",
    label: "Qualified artifact",
    detail: "Packed output and browser receipt",
    kind: "write",
  },
  {
    id: "m05-proof",
    from: "store",
    to: "agent",
    label: "Immutable receipt",
    detail: "Artifact hash and provenance identity",
    kind: "return",
  },
  {
    id: "m06-deliver",
    from: "agent",
    to: "owner",
    label: "Reviewable delivery",
    detail: "Outcome, evidence boundary and next decision",
    kind: "return",
  },
] as const satisfies readonly Message[];

const relations = messages.map((message): DiaxRelation<ReactNode> => {
  const sourceIndex = participantIndex(message.from);
  const targetIndex = participantIndex(message.to);
  const forwards = sourceIndex < targetIndex;
  return {
    id: message.id,
    from: endpointId(message.id, message.from),
    to: endpointId(message.id, message.to),
    label: <MessageLabel index={message.id.slice(1, 3)}>{message.label}</MessageLabel>,
    sourceAnchor: forwards ? "right" : "left",
    targetAnchor: forwards ? "left" : "right",
    pathType: "straight",
    style: message.kind === "return" ? "dashed" : "solid",
    color:
      message.kind === "write" ? "#a96320" : message.kind === "return" ? "#66757c" : "#2c5f7a",
    targetMarker: "arrow",
    gap: 2,
  };
});

export default function AgentReviewSequence() {
  return (
    <DiagramFrame
      data-showcase-corpus="agent-review-sequence"
      eyebrow="Agent protocol · Authored message order"
      title="A delivery is a sequence of reviewable messages"
      description="Each row owns its sender and receiver endpoints. Connect measures those exact DOM points instead of asking for message coordinates."
      caption="At narrow widths the ordered transcript becomes the visible artifact; message meaning never depends on the edge overlay."
      className="w-full max-w-[1120px] [--diax-accent:#2c5f7a] [--diax-frame-bg:#eaf0f2] [--diax-frame-radius:2px] [--diax-frame-shadow:none] [--diax-node-bg:#f3f6f7] [--diax-node-border:#bac5c9] [--diax-node-shadow:none] [--diax-node-text:#172126] [--diax-ui-radius:2px]"
    >
      <MessageLegend />

      <section className="mt-4 hidden border border-[#bac5c9] bg-[#f3f6f7] sm:block" aria-label="Agent review message sequence">
        <ParticipantHeader />
        <ConnectionSurface relations={relations} pathType="straight" className="grid">
          {messages.map((message, index) => (
            <MessageRow key={message.id} message={message} index={index} />
          ))}
        </ConnectionSurface>
      </section>

      <ol
        data-sequence-transcript
        aria-label="Agent review ordered transcript"
        className="m-0 mt-4 grid list-none border-y border-[#bac5c9] p-0 sm:sr-only"
      >
        {messages.map((message, index) => (
          <li
            key={message.id}
            data-sequence-transcript-message={message.id}
            className="grid grid-cols-[2.75rem_minmax(0,1fr)] gap-3 border-t border-[#d3dcdf] py-3 first:border-t-0"
          >
            <span className="font-mono text-[10px] font-bold text-[#2c5f7a]">
              {String(index + 1).padStart(2, "0")}
            </span>
            <span>
              <strong className="block text-[12px] text-[#172126]">
                {participantLabel(message.from)} → {participantLabel(message.to)} · {message.label}
              </strong>
              <small className="mt-1 block text-[10px] leading-4 text-[#5a6970]">
                {message.detail}
              </small>
            </span>
          </li>
        ))}
      </ol>
    </DiagramFrame>
  );
}

function ParticipantHeader() {
  return (
    <header className="grid grid-cols-[4rem_repeat(4,minmax(0,1fr))] border-b border-[#bac5c9]">
      <div className="p-3 font-mono text-[9px] font-bold uppercase tracking-[0.1em] text-[#66757c]">
        Trace
      </div>
      {participants.map((participant) => (
        <div
          key={participant.id}
          data-sequence-participant={participant.id}
          className="border-l border-[#bac5c9] px-3 py-3 text-center"
        >
          <h2 className="m-0 text-[12px] font-semibold text-[#172126]">{participant.label}</h2>
          <p className="m-0 mt-1 font-mono text-[8px] uppercase tracking-[0.08em] text-[#66757c]">
            {participant.detail}
          </p>
        </div>
      ))}
    </header>
  );
}

function MessageRow({ message, index }: { message: Message; index: number }) {
  return (
    <div
      data-sequence-message={message.id}
      className="grid min-h-[76px] grid-cols-[4rem_repeat(4,minmax(0,1fr))] border-t border-[#d3dcdf] first:border-t-0"
    >
      <div className="flex items-center justify-center font-mono text-[10px] font-bold text-[#2c5f7a]">
        {String(index + 1).padStart(2, "0")}
      </div>
      {participants.map((participant) => {
        const endpoint = participant.id === message.from || participant.id === message.to;
        return (
          <div key={participant.id} className="relative border-l border-[#c5d0d4]">
            {endpoint ? (
              <span
                {...connectionTarget(endpointId(message.id, participant.id))}
                aria-hidden="true"
                className="absolute top-1/2 left-1/2 z-10 size-2 -translate-x-1/2 -translate-y-1/2 border border-[#f3f6f7] bg-[#2c5f7a] outline outline-1 outline-[#66757c]"
              />
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

function MessageLabel({ index, children }: { index: string; children: ReactNode }) {
  return (
    <span className="inline-flex items-center gap-1.5 border border-[#bac5c9] bg-[#f3f6f7] px-1.5 py-0.5 font-mono text-[10px] font-semibold whitespace-nowrap text-[#34484f]">
      <span className="text-[#2c5f7a]">{index}</span>
      {children}
    </span>
  );
}

function MessageLegend() {
  return (
    <ul
      aria-label="Sequence message legend"
      className="m-0 grid list-none border-y border-[#bac5c9] p-0 text-[10px] text-[#526169] sm:grid-cols-3"
    >
      <LegendItem label="Request or delivery" color="#2c5f7a" />
      <LegendItem label="Return or acknowledgement" color="#66757c" dashed />
      <LegendItem label="Durable artifact write" color="#a96320" />
    </ul>
  );
}

function LegendItem({ label, color, dashed = false }: { label: string; color: string; dashed?: boolean }) {
  return (
    <li className="flex items-center gap-2 px-3 py-2 sm:border-l sm:first:border-l-0">
      <span
        aria-hidden="true"
        className={`w-8 border-t-2 ${dashed ? "border-dashed" : ""}`}
        style={{ borderColor: color }}
      />
      {label}
    </li>
  );
}

function participantIndex(id: ParticipantId): number {
  return participants.findIndex((participant) => participant.id === id);
}

function participantLabel(id: ParticipantId): string {
  return participants.find((participant) => participant.id === id)?.label ?? id;
}

function endpointId(messageId: string, participantId: ParticipantId): string {
  return `${messageId}-${participantId}`;
}
